const o = require('ospec');

const { romanize } = require('../src/romanize');
const japanese = require('japanese');

o.spec('comparing with "japanese" package (nihonshiki)', () => {
  const validate = kana => {
    const myResult = romanize(kana).result;
    const japaneseResult = japanese.romanize(kana, 'nihon');

    o(myResult).equals(japaneseResult);
  };

  o('matches simple hiragana', () => {
    validate('あいうえお');
    validate('かきくけこ');
    validate('さしすせそ');
    validate('たちつてと');
    validate('なにぬねの');
    validate('はひふへほ');
    validate('まみむめも');
    validate('らりるれろ');
    validate('がぎぐげご');
    validate('ざじずぜぞ');
    validate('だぢづでど');
    validate('ばびぶべぼ');
    validate('ぱぴぷぺぽ');
    validate('やゆよ');
    validate('わを');
    validate('ゐゑ');
  });

  o('matches moraic n', () => {
    validate('たん');
    validate('たんい');
    validate('おんな');
    validate('こんや');
    validate('こにゃ');
  });

  o('matches geminates', () => {
    validate('けっか');
    validate('さっさと');
    validate('ずっと');
    validate('きっぷ');
    validate('ざっし');
    validate('こっち');
    validate('まっちゃ');
    validate('みっつ');
    validate('みっ');
  });

  o('matches palatalized syllables', () => {
    validate('しゃしゅしょ');
    validate('ちゃちゅちょ');
    validate('にゃにゅにょ');
    validate('ひゃひゅひょ');
    validate('じゃじゅじょ');
    validate('ぢゃぢゅぢょ');
  });

  o('matches katakana', () => {
    validate('アイウエオ');
    validate('カキクケコ');
    validate('サシスセソ');
    validate('タチツテト');
    validate('ナニヌネノ');
    validate('ハヒフヘホ');
    validate('マミムメモ');
    validate('ラリルレロ');
    validate('ガギグゲゴ');
    validate('ザジズゼゾ');
    validate('ダヂヅデド');
    validate('バビブベボ');
    validate('パピプペポ');
    validate('ヤユヨ');
    validate('ワヰヱヲ');
    validate('ン');
    validate('ニャニュニョ');
    validate('メッチャ');
  });

  o('punctuation handling', () => {
    validate('－な');
    validate('。');
    validate('、');
  });

  o.spec('matches long vowels when config set to merge', () => {
    o('without punctuation', () => {
      const validate = kana => {
        const myResult = romanize(kana, { mergeLongVowels: true }).result;
        const japaneseResult = japanese.romanize(kana, 'nihon');

        o(myResult).equals(japaneseResult);
      };

      validate('おばあさん');
      validate('じゃあく');
      validate('おにいさん');
      validate('おいしい');
      validate('はいいろ');
      validate('くう');
      validate('みずうみ');
      validate('すうがく');
      validate('ぬれえん');
      validate('おねえさん');
      validate('こおどり');
      validate('こおり');
      validate('おう');
      validate('こうま');
      validate('がっこう');
      validate('きんようび');
      validate('がくせい');
      validate('まねいて');
    });

    o('with punctuation breaking syllables', () => {
      const kana = 'お.う';

      const config = {
        mergeLongVowels: true,
        nonKanaAllowed: true,
      };

      const myResult = romanize(kana, config).result;

      const japaneseResult = japanese.romanize(
        kana.replace('.', '。'),
        'nihon',
      );

      o(myResult).equals(japaneseResult);
    });
  });
});
